effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5; p.x*=acScreenSize.x/max(acScreenSize.y,1.0);
float r=max(length(p),0.006), a=atan(p.y,p.x);
float sector=6.2831853/max(sides,3.0);
float folded=abs(mod(a+0.5*sector,sector)-0.5*sector);
float u=fract(folded/sector*2.0+log(r)*twist);
float v=fract(depth*0.12/r+travel*0.05);
vec4 tunnel=texture2DCv(inputImg.texture,vec2(u,v));
float ribs=pow(1.0-abs(fract(v*8.0)-0.5)*2.0,10.0);
float fog=clamp(r*2.1,0.0,1.0);
tunnel.rgb=mix(tunnel.rgb,tunnel.rgb+vec3(ribs*glow),fog);
tunnel.a*=smoothstep(0.0,0.035,r);
vec4 src=texture2DCv(inputImg.texture,uv);
gl_FragColor=mix(src,tunnel,mixAmount);
}
